            public void onClick(View v) {
                String shape = ""; // Get shape from user interface
                double area = calculateArea(shape);
                resultView.setText("Area: " + area);
            }
        });
    }

    private double calculateArea(String shape) {
        double area = 0.0;
        if (shape.equals("circle")) {
            double radius = Double.parseDouble(inputRadius.getText().toString());
            area = Math.PI * radius * radius;
        } else if (shape.equals("rectangle")) {
            int base = Integer.parseInt(inputBase.getText().toString());
            int height = Integer.parseInt(inputHeight.getText().toString());
            area = base * height;
        } else if (shape.equals("triangle")) {
            double base = Double.parseDouble(inputBase.getText().toString());
            double height = Double.parseDouble(inputHeight.getText().toString());
            area = 0.5 * base * height;
        } 
        // No default case handled for unknown shapes 
        return area;
    }

