import java.util.HashMap;
import java.util.Map;
import java.util.List;
import java.util.ArrayList;

public class MostCommonWords {
    public static List<String> findMostCommonWords(String input) {
        Map<String, Integer> wordCount = new HashMap<>();
        String[] words = input.split(" ");

        for (String word : words) {
            if (wordCount.containsKey(word)) {
                wordCount.put(word, wordCount.get(word) + 1);
            } else {
                wordCount.put(word, 1);
            }
        }

        List<String> mostCommon = new ArrayList<>();
        int maxCount = 0;

        for (Map.Entry<String, Integer> entry : wordCount.entrySet()) {
            if (entry.getValue() > maxCount) {
                mostCommon.clear();
                mostCommon.add(entry.getKey());
                maxCount = entry.getValue();
            } else if (entry.getValue() == maxCount) {
                mostCommon.add(entry.getKey());
            }
        }

        return mostCommon;
    }

    public static void main(String[] args) {
        String text = "hello world hello everyone world hello";
        System.out.println("Most common words: " + findMostCommonWords(text));
    }
}
