function gammaCorrect(colorValue, profile) {
    // Assume colorValue is a hexadecimal string like "#RRGGBB"

    // Convert hex to RGB components
    let r = parseInt(colorValue.slice(1, 3), 16);
    let g = parseInt(colorValue.slice(3, 5), 16);
    let b = parseInt(colorValue.slice(5, 7), 16);

    // Apply gamma correction based on the profile
    switch(profile) {
        case "sRGB":
            r = Math.pow(r / 255, 2.2) * 255;
            g = Math.pow(g / 255, 2.2) * 255;
            b = Math.pow(b / 255, 2.2) * 255;
            break;
        case "Adobe RGB":
            r = Math.pow(r / 255, 2.2) * 255; // Assuming same as sRGB for simplification
            g = Math.pow(g / 255, 2.2) * 255;
            b = Math.pow(b / 255, 2.2) * 255;
            break;
        case "ProPhoto RGB":
            r = Math.pow(r / 255, 1.8) * 255;
            g = Math.pow(g / 255, 1.8) * 255;
            b = Math.pow(b / 255, 1.8) * 255;
            break;
        default:
            throw new Error("Invalid color profile");
    }

    // Ensure values are within the RGB range
    r = Math.max(0, Math.min(255, r));
    g = Math.max(0, Math.min(255, g));
    b = Math.max(0, Math.min(255, b));

    // Return the corrected color value in hexadecimal format
    return "#" + Math.floor(r).toString(16).padStart(2, '0') + 
               Math.floor(g).toString(16).padStart(2, '0') + 
               Math.floor(b).toString(16).padStart(2, '0');
}

// Example usage
